"""
Screen 5 — Configuration review.
Renders a read-only summary of all choices and the exact commands that will run.
"""

import gi
gi.require_version("Gtk", "4.0")
gi.require_version("Adw", "1")

from gi.repository import Gtk, Adw, Pango

from .base import BasePage
from ..state import WizardState
from typing import Callable


class ReviewScreen(BasePage):
    def __init__(self, state: WizardState, go_to: Callable):
        super().__init__(state, go_to, title="Review", tag="review")

    def _build(self):
        self._body.append(
            self.make_page_header(
                "Review configuration",
                "These changes will be applied to your system. "
                "A reboot is required after applying.",
            )
        )

        # Summary group — rebuilt on each on_enter()
        self._summary_group = Adw.PreferencesGroup()
        self._summary_group.set_title("Configuration summary")
        self._body.append(self._summary_group)

        self._btn_row = self.make_button_row(
            back_label="Back",
            back_cb=lambda: self.go_to("back"),
            next_label="Apply & Reboot",
            next_cb=lambda: self.go_to("apply"),
            next_style="destructive-action",
        )
        self._body.append(self._btn_row)

    def on_enter(self):
        """Rebuild summary each time the screen is shown."""
        s = self.state

        # Clear previous summary rows
        child = self._summary_group.get_first_child()
        while child:
            nxt = child.get_next_sibling()
            self._summary_group.remove(child)
            child = nxt

        vendor = s.hardware.cpu_vendor
        iommu_karg = f"{vendor}_iommu=on" if vendor in ("intel", "amd") else "unknown_iommu=on"

        rows = [
            ("IOMMU kernel arg",   iommu_karg),
            ("Additional kargs",   "iommu=pt  rd.driver.pre=vfio-pci"),
            ("NICs for sys-net",   ", ".join(n.iface for n in s.selected_nics) or "None"),
            ("NIC PCI IDs",        ", ".join(n.pci_address for n in s.selected_nics) or "—"),
            ("GPU passthrough",    s.selected_gpu.description if s.gpu_passthrough and s.selected_gpu else "Disabled"),
            ("VMs to provision",   "sys-net, sys-firewall" + (
                                       (", " + ", ".join(s.selected_appvms)) if s.selected_appvms else ""
                                   )),
            ("Initramfs modules",  "vfio  vfio_pci  vfio_iommu_type1"),
            ("SSH access",         "Auto-generated at ~/.config/bulwarkos/infra_key"),
            ("sys-net autostart",  "Enabled"),
            ("sys-firewall autostart", "Enabled"),
            ("Host route",         "default via 10.10.1.254 dev bulwark-avm"),
        ]

        for label, value in rows:
            row = Adw.ActionRow()
            row.set_title(label)
            val_lbl = Gtk.Label(label=value)
            val_lbl.set_ellipsize(Pango.EllipsizeMode.END)
            val_lbl.set_max_width_chars(36)
            val_lbl.add_css_class("monospace")
            val_lbl.add_css_class("dim-label")
            row.add_suffix(val_lbl)
            self._summary_group.add(row)
